def sh(cmd, check=True, timeout=None):
    print("$", cmd if len(cmd) < 300 else cmd[:300] + " ...", flush=True)
    r = subprocess.run(cmd, shell=True, text=True, capture_output=True, timeout=timeout)
    if r.stdout.strip():
        print(r.stdout[-2000:])
    if r.returncode:
        print(r.stderr[-3000:])
        if check:
            raise RuntimeError(f"command failed ({r.returncode})")
    return r.stdout


def kernel_version(mod):
    r = subprocess.run([sys.executable, "-c", f"import {mod}; print({mod}.__version__)"],
                       capture_output=True, text=True)
    return r.stdout.strip() if r.returncode == 0 else None


def v_match(v, target):
    return v is not None and (v == target or v.replace(".0", ".") == target.replace(".0", "."))


def dist_version(dist):
    r = subprocess.run([sys.executable, "-c",
                        f"import importlib.metadata as m; print(m.version('{dist}'))"],
                       capture_output=True, text=True)
    return r.stdout.strip() if r.returncode == 0 else None


