# %% [markdown]
# ## MCES — reported, never gating
#
# Myopic MCES with a `pulp` ILP is slow, so it runs on a fixed random 150-molecule subset of
# `pseudo_c3` and on all of `ts_dec`, for both arms.

# %%
def mces_best(truth, cands, timeout=MCES_TIMEOUT):
    """The smallest myopic-MCES distance from the truth to any candidate. None if unavailable."""
    from myopic_mces.myopic_mces import MCES
    best = None
    for smi, _ in cands:
        try:
            r = MCES(truth, smi, threshold=15, solver=solvers[0], solver_options=dict(msg=0),
                     no_ilp_threshold=False)
            d = float(r[1])
        except Exception:
            continue
        best = d if best is None else min(best, d)
    return best


MCES_OUT = {}
for label, (t_sc, n_sc) in SCORED.items():
    queries = QUERIES[label]
    if label == "pseudo_c3" and len(queries) > MCES_C3_SUBSET:
        rng = np.random.default_rng(SEED)
        pick = set(np.asarray([q["molecule_id"] for q in queries])[
            np.sort(rng.choice(len(queries), MCES_C3_SUBSET, replace=False))])
    else:
        pick = {q["molecule_id"] for q in queries}
    treat = p3e.ChunkStore(CANDS, f"{WINNER}_{label}").load()
    null = NULL_STORES[label].load()
    rows, t0 = [], time.time()
    for i, q in enumerate([q for q in queries if q["molecule_id"] in pick], 1):
        sel_t = nd.select_top25(treat.get(q["molecule_id"], []), "maxmin")
        sel_n = nd.select_top25(null.get(q["molecule_id"], []), "maxmin")
        rows.append(dict(molecule_id=q["molecule_id"],
                         mces_treatment=mces_best(q["can"], sel_t),
                         mces_null=mces_best(q["can"], sel_n)))
        if i % 25 == 0:
            print(f"[mces {label}] {i}/{len(pick)}  {(time.time() - t0) / i:.1f}s/mol", flush=True)
    df = pd.DataFrame(rows)
    df.to_parquet(CANDS / f"mces_{label}.parquet", index=False)
    MCES_OUT[label] = dict(n=len(df),
                           median_treatment=float(df.mces_treatment.median(skipna=True))
                           if df.mces_treatment.notna().any() else None,
                           median_null=float(df.mces_null.median(skipna=True))
                           if df.mces_null.notna().any() else None,
                           seconds=round(time.time() - t0))
    print(f"[mces {label}] median {MCES_OUT[label]['median_treatment']} vs null "
          f"{MCES_OUT[label]['median_null']} over {len(df)} molecules")
GATE["mces"] = MCES_OUT
save_gate()

# %% [markdown]
