#
# **G3.1** the winner beats `RandomDeNovo` on median top-25 max Tanimoto by ≥ 0.10 on `pseudo_c3`,
# under `maxmin`. **G3.2** the loss converged. Both must hold. `ts_dec` is reported and is **not**
# part of the verdict.

# %%
V = p3e.g3_verdict(RESULTS["pseudo_c3"]["treatment"], RESULTS["pseudo_c3"]["null"],
                   threshold=G3_THRESHOLD, converged=GATE.get("g32_converged"))
GATE.update(verdict=V["verdict"], items=V["items"], g3=V, finished=time.strftime("%Y-%m-%d %H:%M"))
save_gate()

print("=" * 88)
print(f"G3 VERDICT: {V['verdict']}")
print("=" * 88)
c3t, c3n = RESULTS["pseudo_c3"]["treatment"], RESULTS["pseudo_c3"]["null"]
print(f"G3.1 {V['items']['G3.1']}  pseudo_c3 median top-25 max Tanimoto: "
      f"{WINNER} {V['treatment_median']:.4f} vs RandomDeNovo {V['null_median']:.4f} "
      f"-> delta {V['delta']:+.4f} (need >= +{G3_THRESHOLD})")
print(f"G3.2 {V['items'].get('G3.2', 'n/a')}  converged (patience 5 reached and the best epoch is "
      f"not the last), from train_meta.json")
