print(f"winner                {WINNER} (selected on the dec_val subset, not on pseudo_c3)")
print(f"bake-off (dec_val)    " + ", ".join(
    f"{a} {s['median_maxtan_maxmin']:.4f}" for a, s in (EV.get("bake_off") or {}).items()))
print(f"exact@1/10/25         {c3t['exact1_maxmin']:.4f} / {c3t['exact10_maxmin']:.4f} / "
      f"{c3t['exact25_maxmin']:.4f}   (null {c3n['exact25_maxmin']:.4f})")
print(f"cands/mol median      {c3t['median_n_cands']:.0f}  zero-candidate share "
      f"{c3t['zero_cand_share']:.3f}")
ts = RESULTS.get("ts_dec", {})
if ts:
    print(f"ts_dec (reported)     median maxTan {ts['treatment']['median_maxtan_maxmin']:.4f} vs "
          f"null {ts['null']['median_maxtan_maxmin']:.4f}, exact@25 "
          f"{ts['treatment']['exact25_maxmin']:.4f}")
print(f"MCES (reported)       {GATE['mces']}")
if c3t["median_n_cands"] < 25:
    print("\n[NOTE] the median molecule yields fewer than 25 candidates, so the selector is largely "
          "inert and G3.1 is really a funnel measurement. Record this beside the verdict.")
