if V["verdict"] == "PASS":
    print("Next: P4-oracle. G4.0 is the kill gate: oracle-formula exact@25 < 0.01 on pseudo_c3 -> stop.")
else:
    print("G3 FAILED. Per gate_report.md G3 decision rule 2 the only move is the single "
          "pre-registered rescue, once: pretrain as a SELFIES LM on the MassSpecGym 4M molecule "
          "set with cross-attention off, fine-tune, and re-run G3. If it fails again, specs_novel "
          "ends (protocol 2). Do not tune the search or the threshold instead.")
print(f"\ngate json: {OUT / 'p3_gate.json'}  -> upload into specs_novel/ (check the path)")
